<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Conway's Game of Life</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: #1a1a2e;
    color: #eee;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    overflow: hidden;
  }

  h1 {
    font-size: 2rem;
    margin-bottom: 1rem;
    color: #e94560;
    text-shadow: 0 0 10px rgba(233, 69, 96, 0.5);
    letter-spacing: 2px;
  }

  .controls {
    display: flex;
    gap: 1rem;
    margin-bottom: 1rem;
  }

  button {
    background: #16213e;
    color: #eee;
    border: 2px solid #0f3460;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.2s ease;
    border-radius: 8px;
    font-weight: 600;
  }

  button:hover {
    background: #e94560;
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(233, 69, 96, 0.3);
  }

  button.active {
    background: #e94560;
    border-color: #e94560;
    animation: pulse 1s infinite;
  }

  @keyframes pulse {
    0%, 100% { box-shadow: 0 0 10px rgba(233, 69, 96, 0.5); }
    50% { box-shadow: 0 0 20px rgba(233, 69, 96, 0.8); }
  }

  #life-container {
    position: relative;
    border: 3px solid #0f3460;
    border-radius: 12px;
    overflow: hidden;
  }

  canvas#life {
    display: block;
    cursor: crosshair;
  }

  .stats {
    margin-top: 1rem;
    font-size: 0.9rem;
    color: #aaa;
  }
</style>
</head>
<body>
<h1>GAME OF LIFE</h1>
<div class="controls">
  <button id="step">▶ Step</button>
  <button id="play">⏯ Play/Pause</button>
  <button id="random">🎲 Random</button>
  <button id="clear">🗑 Clear</button>
</div>
<div id="life-container">
  <canvas id="life" width="600" height="600"></canvas>
</div>
<div class="stats">
  Cells: <span id="cell-count">0</span> | Generation: <span id="gen-count">0</span>
</div>

<script>
(function() {
  'use strict';

  const CELL_SIZE = 12;
  const PADDING = 4;

  // Grid dimensions - at least 40x40
  const W = 50;
  const H = 50;

  // State
  let grid = createGrid();
  let generation = 0;
  let isPlaying = false;
  let playInterval = null;
  let isDrawing = false;

  function createGrid() {
    return Array.from({ length: H }, () => new Uint8Array(W));
  }

  // API - exposed on window.life
  const lifeAPI = {
    w: W,
    h: H,

    get(x, y) {
      if (x < 0 || x >= W || y < 0 || y >= H) return 0;
      return grid[y][x];
    },

    set(x, y, v) {
      if (x < 0 || x >= W || y < 0 || y >= H) return;
      grid[y][x] = v ? 1 : 0;
    },

    step() {
      generation++;
      const nextGrid = createGrid();

      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          let neighbors = countNeighbors(x, y);

          if (grid[y][x] === 1) {
            // Live cell survives with 2 or 3 neighbors
            nextGrid[y][x] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
          } else {
            // Dead cell becomes alive with exactly 3 neighbors
            nextGrid[y][x] = (neighbors === 3) ? 1 : 0;
          }
        }
      }

      grid = nextGrid;

      updateStats();
      draw();
    },

    clear() {
      for (let y = 0; y < H; y++) {
        grid[y].fill(0);
      }
      generation = 0;
      updateStats();
      draw();
    },

    randomize() {
      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          grid[y][x] = Math.random() < 0.3 ? 1 : 0;
        }
      }
      generation = 0;
      updateStats();
      draw();
    },

    _internalCountNeighbors(x, y) {
      let count = 0;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dy === 0) continue;
          const nx = x + dx;
          const ny = y + dy;
          count += grid[ny][nx];
        }
      }
      return count;
    },

    _internalStep() {
      // Simultaneous update - all cells computed from current generation
      const nextGrid = createGrid();

      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          let neighbors = 0;

          // Count neighbors manually to ensure simultaneous computation
          for (let dy = -1; dy <= 1; dy++) {
            for (let dx = -1; dx <= 1; dx++) {
              if (dx === 0 && dy === 0) continue;
              const nx = x + dx;
              const ny = y + dy;

              // Edges are dead - cells outside grid count as 0
              if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
                neighbors += grid[ny][nx];
              }
            }
          }

          if (grid[y][x] === 1) {
            // Live cell survives with 2 or 3 neighbors
            nextGrid[y][x] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
          } else {
            // Dead cell becomes alive with exactly 3 neighbors
            nextGrid[y][x] = (neighbors === 3) ? 1 : 0;
          }
        }
      }

      grid = nextGrid;
      generation++;
      updateStats();
      draw();
    },

    _internalPlay() {
      if (!isPlaying) return;
      this._internalStep();
      playInterval = setTimeout(() => {
        this._internalPlay();
      }, 100);
    }
  };

  // Expose API on window
  window.life = lifeAPI;

  function countNeighbors(x, y) {
    let count = 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        count += grid[ny][nx];
      }
    }
    return count;
  }

  function draw() {
    const canvas = document.getElementById('life');
    const ctx = canvas.getContext('2d');

    // Clear canvas with dark background
    ctx.fillStyle = '#0a0a1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw grid lines (subtle)
    ctx.strokeStyle = 'rgba(15, 52, 96, 0.3)';
    ctx.lineWidth = 0.5;

    for (let x = PADDING; x < canvas.width - PADDING; x += CELL_SIZE) {
      ctx.beginPath();
      ctx.moveTo(x, PADDING);
      ctx.lineTo(x, canvas.height - PADDING);
      ctx.stroke();
    }

    for (let y = PADDING; y < canvas.height - PADDING; y += CELL_SIZE) {
      ctx.beginPath();
      ctx.moveTo(PADDING, y);
      ctx.lineTo(canvas.width - PADDING, y);
      ctx.stroke();
    }

    // Draw alive cells
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (grid[y][x] === 1) {
          const px = PADDING + x * CELL_SIZE;
          const py = PADDING + y * CELL_SIZE;

          // Draw cell with glow effect
          ctx.fillStyle = '#e94560';
          ctx.shadowColor = 'rgba(233, 69, 96, 0.8)';
          ctx.shadowBlur = 8;
          ctx.fillRect(px + 1, py + 1, CELL_SIZE - 2, CELL_SIZE - 2);

          // Slightly brighter center
          ctx.fillStyle = '#ff6b8a';
          ctx.fillRect(px + 3, py + 3, CELL_SIZE - 6, CELL_SIZE - 6);
        }
      }
    }

    // Reset shadow for other drawings
    ctx.shadowBlur = 0;

    // Draw generation counter on canvas
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    ctx.font = '14px monospace';
    ctx.fillText(`Gen: ${generation}`, PADDING + 10, PADDING - 5);
  }

  function updateStats() {
    let count = 0;
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (grid[y][x] === 1) count++;
      }
    }
    document.getElementById('cell-count').textContent = count;
    document.getElementById('gen-count').textContent = generation;
  }

  // Canvas interaction - click and drag to toggle cells
  const canvas = document.getElementById('life');

  function getCellPos(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;

    const x = Math.floor((e.clientX - rect.left) * scaleX);
    const y = Math.floor((e.clientY - rect.top) * scaleY);

    return { x, y };
  }

  canvas.addEventListener('mousedown', (e) => {
    isDrawing = true;
    const pos = getCellPos(e);
    toggleCell(pos.x, pos.y);
  });

  canvas.addEventListener('mousemove', (e) => {
    if (!isDrawing) return;
    const pos = getCellPos(e);
    // Only update every other frame to avoid flickering during drag
    if (Math.random() > 0.5) {
      toggleCell(pos.x, pos.y);
    }
  });

  canvas.addEventListener('mouseup', () => {
    isDrawing = false;
  });

  canvas.addEventListener('mouseleave', () => {
    isDrawing = false;
  });

  // Touch support for mobile
  canvas.addEventListener('touchstart', (e) => {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousedown', {
      clientX: touch.clientX,
      clientY: touch.clientY
    });
    canvas.dispatchEvent(mouseEvent);
  }, { passive: false });

  canvas.addEventListener('touchmove', (e) => {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousemove', {
      clientX: touch.clientX,
      clientY: touch.clientY
    });
    canvas.dispatchEvent(mouseEvent);
  }, { passive: false });

  canvas.addEventListener('touchend', () => {
    isDrawing = false;
  });

  function toggleCell(x, y) {
    if (x < 0 || x >= W || y < 0 || y >= H) return;

    // Toggle with visual feedback
    grid[y][x] = grid[y][x] ? 0 : 1;
    draw();
    updateStats();
  }

  // Button handlers
  document.getElementById('step').addEventListener('click', () => {
    lifeAPI.step();
  });

  document.getElementById('play').addEventListener('click', () => {
    if (isPlaying) {
      isPlaying = false;
      clearTimeout(playInterval);
      document.getElementById('play').textContent = '⏯ Play/Pause';
      document.getElementById('play').classList.remove('active');
    } else {
      isPlaying = true;
      document.getElementById('play').textContent = '⏸ Pause';
      document.getElementById('play').classList.add('active');

      // Use setTimeout for each step to ensure synchronous behavior
      playInterval = setTimeout(() => {
        if (isPlaying) {
          lifeAPI._internalStep();
          playInterval = setTimeout(playInterval, 100);
        }
      }, 100);
    }
  });

  document.getElementById('random').addEventListener('click', () => {
    lifeAPI.randomize();
  });

  document.getElementById('clear').addEventListener('click', () => {
    lifeAPI.clear();
  });

  // Initialize with a classic pattern - glider in corner
  grid[0][1] = 1;
  grid[0][2] = 1;
  grid[1][3] = 1;
  grid[2][0] = 1;
  grid[2][1] = 1;

  draw();
  updateStats();

})();
</script>
</body>
</html>
